def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    opp_budgets = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            opp_budgets.append(float(opp.get('budget', 0)))
            if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            if opp.get('budget', 0) >= 900:
                rich_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                try:
                    prev_bids.append(float(prev.get('bid')))
                except Exception:
                    pass

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, 90.0))
        return float(min(budget, 20.0))

    highest_prev = max(prev_bids) if prev_bids else 130.0
    median_anchor = 128.0
    if prev_bids:
        s = sorted(prev_bids)
        median_anchor = s[int(len(s) // 2)]

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water_days >= 2:
        danger += 3
    elif no_water_days >= 1:
        danger += 2

    endgame = day >= 8

    if danger >= 5:
        target = max(146.0, highest_prev + 4.0)
    elif danger >= 3:
        target = max(138.0, median_anchor + 6.0, highest_prev - 1.0)
    else:
        if supply >= 23:
            target = 36.0
        elif supply >= 21:
            target = 62.0
        elif supply >= 19:
            target = 96.0
        elif supply >= 17:
            target = max(122.0, median_anchor + 2.0)
        else:
            target = max(136.0, highest_prev + 2.0)

    target += scarcity * 10.0
    target += urgent_opp * 1.5
    target += rich_opp * 1.0
    if endgame and (hp <= 6 or no_water_days >= 1):
        target += 6.0

    reserve = 0.0
    if day <= 3 and hp >= 7 and no_water_days == 0:
        reserve = 25.0
    elif day <= 6 and hp >= 5 and no_water_days == 0:
        reserve = 10.0

    max_affordable = max(0.0, budget - reserve)
    if danger >= 5:
        max_affordable = budget

    bid = min(target, max_affordable)

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, 150.0))
    elif hp <= 4 or no_water_days >= 1:
        bid = min(budget, max(bid, 138.0))

    if supply >= 23 and hp >= 7 and no_water_days == 0:
        bid = min(bid, min(budget, 45.0))

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Base aggressiveness from yesterday
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        second_prev_bid = sorted(yesterday_bids)[-2] if len(yesterday_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Estimate how tight supply is
    # If supply is near min, water is scarce: bid higher.
    scarcity = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    scarcity = max(0.0, min(1.0, scarcity))

    # If we've already gone without water, increase pressure quickly.
    urgency = 0.0
    if no_water_days >= 3:
        urgency = 0.95
    elif no_water_days == 2:
        urgency = 0.75
    elif no_water_days == 1:
        urgency = 0.45
    else:
        urgency = 0.25

    # If our hp is low, we must secure water.
    hp_pressure = 0.0
    if hp <= 1.5:
        hp_pressure = 1.0
    elif hp <= 3.0:
        hp_pressure = 0.75
    elif hp <= 5.0:
        hp_pressure = 0.45
    else:
        hp_pressure = 0.25

    # Target bid: slightly above the typical aggressive level from yesterday.
    # Use highest_prev_bid as a cap reference, but don't fully chase it.
    if highest_prev_bid > 0:
        # If others were extremely aggressive, match a fraction.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            target = highest_prev_bid * (0.55 + 0.25 * scarcity + 0.15 * hp_pressure) + (urgency * 5.0)
        else:
            target = max(second_prev_bid * 0.85, DAILY_SALARY * 0.55) + (scarcity * 10.0) + (urgency * 6.0)
    else:
        target = DAILY_SALARY * (0.55 + 0.2 * scarcity + 0.15 * hp_pressure) + (urgency * 6.0)

    # Convert to feasible bid: can't exceed budget.
    # Also avoid overbidding when budget is low.
    # Keep a floor to avoid being undercut too much when supply is scarce.
    floor_bid = DAILY_SALARY * (0.45 + 0.25 * scarcity + 0.15 * hp_pressure)
    bid = max(floor_bid, target)

    bid = min(bid, budget)

    # If budget is extremely low, still bid what we can to prevent further water loss.
    if budget <= 1.0:
        return 0.0

    # Safety: if our hp is critically low, use most of budget.
    if hp <= 2.0:
        bid = max(bid, budget * 0.75)
        bid = min(bid, budget)

    return float(bid)
